using System;
using System.Net;
using System.Net.Mail;
using System.Runtime.InteropServices;
using System.Text;
using System.Collections.Generic;

namespace EmailService
{
    public class FeatureFlags
    {
        public bool EnableExtendedHeaders { get; set; } = false;
        public bool EnableNativeRenderer { get; set; } = false;
        public int MaxRecipients { get; set; } = 50;
        public int HeaderBufferSize { get; set; } = 256;
    }

    public static class NativeRenderer
    {
        [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr memcpy(IntPtr dest, byte[] src, int count);

        [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr memset(IntPtr dest, int c, int count);

        public static unsafe string RenderHeaderBlock(List<string> headers, int bufferSize)
        {
            IntPtr buffer = Marshal.AllocHGlobal(bufferSize);
            try
            {
                memset(buffer, 0, bufferSize);
                int offset = 0;
                foreach (var header in headers)
                {
                    byte[] headerBytes = Encoding.UTF8.GetBytes(header + "\r\n");
                    int remaining = bufferSize - offset;
                    int copyLen = ComputeSafeCopyLength(headerBytes.Length, remaining);
                    if (copyLen > 0)
                    {
                        memcpy(IntPtr.Add(buffer, offset), headerBytes, copyLen);
                        offset += copyLen;
                    }
                }
                byte[] managed = new byte[offset];
                Marshal.Copy(buffer, managed, 0, offset);
                return Encoding.UTF8.GetString(managed);
            }
            finally
            {
                Marshal.FreeHGlobal(buffer);
            }
        }

        private static int ComputeSafeCopyLength(int dataLen, int remaining)
        {
            if (remaining <= 0) return 0;
            return dataLen < remaining ? dataLen : remaining;
        }
    }

    public class EmailRequest
    {
        public string From { get; set; }
        public List<string> To { get; set; } = new List<string>();
        public string Subject { get; set; }
        public string Body { get; set; }
        public Dictionary<string, string> CustomHeaders { get; set; } = new Dictionary<string, string>();
    }

    public class EmailSender
    {
        private readonly FeatureFlags _flags;

        public EmailSender(FeatureFlags flags)
        {
            _flags = flags;
        }

        public string Send(EmailRequest request)
        {
            if (request.To.Count > _flags.MaxRecipients)
                throw new ArgumentException("Too many recipients");

            var headerList = BuildHeaders(request);
            string renderedHeaders;

            if (_flags.EnableNativeRenderer)
            {
                int totalEstimate = EstimateTotalHeaderSize(headerList);
                int allocSize = DetermineBufferAllocation(totalEstimate);
                renderedHeaders = NativeRenderer.RenderHeaderBlock(headerList, allocSize);
            }
            else
            {
                renderedHeaders = string.Join("\r\n", headerList);
            }

            return FormatMessage(renderedHeaders, request.Body);
        }

        private int EstimateTotalHeaderSize(List<string> headers)
        {
            int total = 0;
            foreach (var h in headers)
                total += Encoding.UTF8.GetByteCount(h) + 2;
            return total;
        }

        private int DetermineBufferAllocation(int estimatedSize)
        {
            int baseSize = _flags.HeaderBufferSize;
            return Math.Max(baseSize, estimatedSize + 64);
        }

        private static string SanitizeHeaderValue(string value)
        {
            if (value == null) return string.Empty;
            // Prevent CRLF / email header injection by stripping line breaks.
            return value.Replace("\r", string.Empty).Replace("\n", string.Empty);
        }

        private List<string> BuildHeaders(EmailRequest request)
        {
            var headers = new List<string>();
            headers.Add($"From: {SanitizeHeaderValue(request.From)}");

            var sanitizedTo = new List<string>();
            foreach (var to in request.To)
                sanitizedTo.Add(SanitizeHeaderValue(to));
            headers.Add($"To: {string.Join(", ", sanitizedTo)}");

            headers.Add($"Subject: {SanitizeHeaderValue(request.Subject)}");
            headers.Add($"Date: {DateTime.UtcNow:R}");
            headers.Add("MIME-Version: 1.0");

            if (_flags.EnableExtendedHeaders && request.CustomHeaders != null)
            {
                foreach (var kvp in request.CustomHeaders)
                {
                    headers.Add($"X-{SanitizeHeaderValue(kvp.Key)}: {SanitizeHeaderValue(kvp.Value)}");
                }
            }
            return headers;
        }

        private string FormatMessage(string headers, string body)
        {
            return $"{headers}\r\n\r\n{body}";
        }
    }
}
